mapper.insert:

    SELECT
        'EDCT'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(EDUCATION_NO), LENGTH('EDCT' ) + 1)), 0) + 1, 6, '0')
    FROM EDUCATION
   WHERE RESUME_NO = #{resumeNo}

INSERT INTO EDUCATION (
	EDUCATION_NO
	, RESUME_NO
	, HIGHEST_EDUCATION_CODE
	, SCHOOL_NAME
	, GRADUATE_YN
	, TRANSFER_YN
	, ENTRANCE_DATE
	, GRADUATE_DATE
	, LOCATION
	, DEPARTMENT_CODE
) VALUES (
	#{educationNo}
	, #{resumeNo}
	, #{highestEducationCode}
	, #{schoolName}
	, #{graduateYn}
	, #{transferYn}
	, REPLACE(#{entranceDate}, '-', '')
	, REPLACE(#{graduateDate}, '-', '')
	, #{location}
	, #{departmentCode}
)

mapper.update:
UPDATE EDUCATION 
   SET HIGHEST_EDUCATION_CODE = #{highestEducationCode}
   	   , SCHOOL_NAME = #{schoolName}
   	   , GRADUATE_YN = #{graduateYn}
   	   , TRANSFER_YN = #{transferYn}
   	   , ENTRANCE_DATE = REPLACE(#{entranceDate}, '-', '')
   	   , GRADUATE_DATE = REPLACE(#{graduateDate}, '-', '')
   	   , LOCATION = #{location}
   	   , DEPARTMENT_CODE = #{departmentCode} 
 WHERE EDUCATION_NO = #{educationNo} 
   AND RESUME_NO = #{resumeNo}

mapper.delete:
DELETE FROM EDUCATION 
 WHERE EDUCATION_NO = #{educationNo} 
   AND RESUME_NO = #{resumeNo}
